/*
 * TEKO offline DataTables-compatible implementation.
 * Implements only the API actually used by this Config Manager.
 */
(function ($) {
  'use strict';
  if (!$ || !$.fn) throw new Error('jQuery is required');

  const instances = new WeakMap();

  function arrLike(nodes) {
    const a = Array.from(nodes || []);
    a.toArray = () => a.slice();
    return a;
  }

  function escapeRegExp(v) {
    return String(v).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  class DT {
    constructor(table, opts) {
      this.table = table;
      this.opts = Object.assign({
        paging: true, searching: true, lengthChange: true, info: true,
        pageLength: 10, lengthMenu: [[10,25,50],[10,25,50]],
        order: []
      }, opts || {});
      this.globalSearch = '';
      this.columnSearch = new Map();
      this.page = 0;
      this.pageLength = Number(this.opts.pageLength) || 10;
      this.order = Array.isArray(this.opts.order) ? this.opts.order.slice() : [];
      this.originalRows = Array.from(table.tBodies[0]?.rows || []);
      this.currentRows = [];
      this.filteredRows = [];
      this._wrap();
      this._bindHeader();
      this.draw();
    }

    _wrap() {
      const table = this.table;
      table.classList.add('dataTable');
      if (table.parentElement?.classList.contains('dataTables_wrapper')) {
        this.wrapper = table.parentElement; return;
      }
      const wrapper = document.createElement('div');
      wrapper.className = 'dataTables_wrapper';
      table.parentNode.insertBefore(wrapper, table);
      wrapper.appendChild(table);
      this.wrapper = wrapper;

      if (this.opts.searching) {
        const filter = document.createElement('div');
        filter.className = 'dataTables_filter';
        const label = document.createElement('label');
        const input = document.createElement('input');
        input.type = 'search';
        input.placeholder = this.opts.language?.searchPlaceholder || '';
        const caption = this.opts.language?.search ?? 'Search:';
        if (caption) label.append(document.createTextNode(caption + ' '));
        label.appendChild(input); filter.appendChild(label);
        wrapper.insertBefore(filter, table);
        input.addEventListener('input', () => { this.globalSearch = input.value; this.page = 0; this.draw(); });
      }

      const footer = document.createElement('div');
      footer.className = 'd-flex justify-content-between align-items-center gap-3 mt-2 flex-wrap';

      if (this.opts.lengthChange) {
        const length = document.createElement('div');
        length.className = 'dataTables_length';
        const label = document.createElement('label');
        label.append(document.createTextNode('Show '));
        const select = document.createElement('select');
        let vals = this.opts.lengthMenu;
        if (Array.isArray(vals) && Array.isArray(vals[0])) vals = vals[0];
        (vals || [10,25,50]).forEach(v => {
          const o = document.createElement('option'); o.value = v; o.textContent = v;
          if (Number(v) === this.pageLength) o.selected = true;
          select.appendChild(o);
        });
        select.addEventListener('change', () => { this.pageLength = Number(select.value) || 10; this.page = 0; this.draw(); });
        label.appendChild(select); label.append(document.createTextNode(' entries'));
        length.appendChild(label); footer.appendChild(length);
        this.lengthBox = length;
      }

      if (this.opts.info) {
        const info = document.createElement('div'); info.className = 'dataTables_info';
        footer.appendChild(info); this.infoBox = info;
      }

      if (this.opts.paging) {
        const paginate = document.createElement('div'); paginate.className = 'dataTables_paginate';
        footer.appendChild(paginate); this.pageBox = paginate;
      }
      wrapper.appendChild(footer);
    }

    _bindHeader() {
      const ths = Array.from(this.table.tHead?.rows?.[0]?.cells || []);
      const disabled = new Set();
      for (const cd of (this.opts.columnDefs || [])) {
        if (cd.orderable === false) {
          for (let idx of (Array.isArray(cd.targets) ? cd.targets : [cd.targets])) {
            if (idx < 0) idx = ths.length + idx;
            disabled.add(idx);
          }
        }
      }
      ths.forEach((th, idx) => {
        th.dataset.dtOrderable = disabled.has(idx) ? 'false' : 'true';
        if (disabled.has(idx)) return;
        th.addEventListener('click', () => {
          const cur = this.order.find(x => Number(x[0]) === idx);
          this.order = [[idx, cur && cur[1] === 'asc' ? 'desc' : 'asc']];
          this.draw();
        });
      });
    }

    _cellText(row, idx) { return (row.cells[idx]?.textContent || '').trim(); }

    _apply() {
      let rows = this.originalRows.slice();
      const g = this.globalSearch.trim().toLowerCase();
      if (g) rows = rows.filter(r => r.textContent.toLowerCase().includes(g));

      for (const [idx, spec] of this.columnSearch.entries()) {
        if (!spec.value) continue;
        rows = rows.filter(r => {
          const text = this._cellText(r, idx);
          if (spec.regex) {
            try { return new RegExp(spec.value, spec.smart === false ? '' : 'i').test(text); }
            catch (_) { return text.includes(spec.value); }
          }
          return text.toLowerCase().includes(String(spec.value).toLowerCase());
        });
      }

      const orders = this.order || [];
      if (orders.length) {
        rows.sort((a,b) => {
          for (const [idxRaw, dir] of orders) {
            const idx = Number(idxRaw);
            const av = this._cellText(a, idx), bv = this._cellText(b, idx);
            const an = Number(av.replace(/[^0-9.+-]/g,'')), bn = Number(bv.replace(/[^0-9.+-]/g,''));
            let cmp = (!Number.isNaN(an) && !Number.isNaN(bn) && av !== '' && bv !== '')
              ? an-bn : av.localeCompare(bv, undefined, {numeric:true, sensitivity:'base'});
            if (cmp) return dir === 'desc' ? -cmp : cmp;
          }
          return 0;
        });
      }
      this.filteredRows = rows;
      return rows;
    }

    draw() {
      const rows = this._apply();
      const tbody = this.table.tBodies[0];
      Array.from(tbody.rows).forEach(r => r.style.display = 'none');

      const pages = this.opts.paging ? Math.max(1, Math.ceil(rows.length / this.pageLength)) : 1;
      if (this.page >= pages) this.page = pages - 1;
      const start = this.opts.paging ? this.page * this.pageLength : 0;
      const end = this.opts.paging ? Math.min(rows.length, start + this.pageLength) : rows.length;
      this.currentRows = rows.slice(start, end);
      this.currentRows.forEach(r => r.style.display = '');

      const ths = Array.from(this.table.tHead?.rows?.[0]?.cells || []);
      ths.forEach(th => th.classList.remove('dt-sort-asc','dt-sort-desc'));
      if (this.order.length) {
        const [idx, dir] = this.order[0];
        ths[Number(idx)]?.classList.add(dir === 'desc' ? 'dt-sort-desc' : 'dt-sort-asc');
      }

      if (this.infoBox) this.infoBox.textContent = rows.length
        ? `Showing ${start+1} to ${end} of ${rows.length} entries`
        : 'Showing 0 to 0 of 0 entries';

      this._renderPages(pages);
      if (typeof this.opts.drawCallback === 'function') {
        try { this.opts.drawCallback.call({api: () => this}); } catch (e) { console.error(e); }
      }
      return this;
    }

    _renderPages(pages) {
      if (!this.pageBox) return;
      const box = this.pageBox; box.textContent = '';
      const add = (label, page, disabled, current) => {
        const b = document.createElement('button'); b.type='button';
        b.className='paginate_button' + (disabled?' disabled':'') + (current?' current':'');
        b.textContent=label; b.disabled=!!disabled;
        b.addEventListener('click',()=>{ if (!disabled){ this.page=page; this.draw(); }});
        box.appendChild(b);
      };
      add(this.opts.language?.paginate?.first || 'First',0,this.page===0,false);
      const max=7, from=Math.max(0,Math.min(this.page-3,pages-max)), to=Math.min(pages,from+max);
      for(let p=from;p<to;p++) add(String(p+1),p,false,p===this.page);
      add(this.opts.language?.paginate?.last || 'Last',pages-1,this.page>=pages-1,false);
    }

    search(value) { if (value === undefined) return this.globalSearch; this.globalSearch=String(value||''); this.page=0; return this; }

    column(index, opts) {
      const self=this, idx=Number(index);
      return {
        search(value, regex, smart) {
          if (value === undefined) return self.columnSearch.get(idx)?.value || '';
          self.columnSearch.set(idx,{value:String(value||''),regex:!!regex,smart});
          self.page=0; return self;
        },
        data() {
          const src = opts?.page === 'current' ? self.currentRows : self.filteredRows;
          const vals = src.map(r => self._cellText(r,idx));
          return {each(fn){ vals.forEach((v,i)=>fn(v,i)); return this; }, toArray(){return vals.slice();}};
        }
      };
    }

    rows(opts) {
      let src = this.filteredRows;
      if (opts?.page === 'current') src = this.currentRows;
      if (opts?.search === 'applied') src = this.filteredRows;
      const nodes = arrLike(src);
      return {nodes(){return nodes;}};
    }

    api() { return this; }
  }

  $.fn.DataTable = function (opts) {
    const el = this[0];
    if (!el) return null;
    let inst = instances.get(el);
    if (!inst) { inst = new DT(el, opts || {}); instances.set(el, inst); }
    return inst;
  };
  $.fn.dataTable = $.fn.DataTable;
  $.fn.DataTable.isDataTable = function (obj) {
    const el = obj && obj.jquery ? obj[0] : obj;
    return !!(el && instances.has(el));
  };
})(window.jQuery);
